content/flashcard-data/sem3/csi247/heaps:
export const flashcardData = [
  { front: "Min-Heap Property", back: "Every parent node is less than or equal to its children. The root is always the minimum element." },
  { front: "Max-Heap Property", back: "Every parent node is greater than or equal to its children. The root is always the maximum element." },
  { front: "Heap Array Formulas (0-indexed)", back: "Left Child: 2i + 1. Right Child: 2i + 2. Parent: floor((i - 1) / 2)." },
  { front: "Heapify-Up (Insert)", back: "Place new element at the end. Compare with parent; if it violates heap property, swap and repeat. Time: O(log N)." },
  { front: "Heapify-Down (Extract)", back: "Replace root with last element. Compare with children; swap with the smallest/largest child if violated. Repeat. Time: O(log N)." },
  { front: "Build Heap Complexity", back: "O(N). By starting heapify-down from the last non-leaf node up to the root, the math converges to linear time, not O(N log N)." },
  { front: "Priority Queue", back: "An abstract data type where elements are dequeued based on priority rather than insertion order. Typically backed by a Binary Heap." },
  { front: "Top-K Elements Pattern", back: "Use a Min-Heap of size K. Iterate array: if heap < K, push. If element > heap.peek(), pop and push. Time: O(N log K)." }
];

content/quiz-data/sem3/csi247/heaps-and-:
export const quizData = [
  { question: "What is the time complexity to build a valid heap from an arbitrary array of N elements?", options: ["O(1)", "O(log N)", "O(N)", "O(N log N)"], correctIndex: 2, explanation: "While a single heapify takes O(log N), the buildHeap algorithm runs in O(N) time because most nodes are near the bottom and require very few swaps." },
  { question: "In a 0-indexed array representing a binary heap, where is the left child of the node at index i?", options: ["2i", "2i + 1", "2i + 2", "i / 2"], correctIndex: 1, explanation: "The mathematical mapping for 0-indexed arrays places the left child at 2i + 1 and the right child at 2i + 2." },
  { question: "To efficiently find the K largest elements in a stream of N numbers, which data structure is optimal?", options: ["Max-Heap of size N", "Min-Heap of size K", "Sorted Array", "Hash Set"], correctIndex: 1, explanation: "A Min-Heap of size K keeps the smallest of the 'top K' at the root. You only do O(log K) work when a new number is larger than the root." },
  { question: "What is the worst-case time complexity to insert an element into a Priority Queue backed by a binary heap?", options: ["O(1)", "O(log N)", "O(N)", "O(N log N)"], correctIndex: 1, explanation: "Insertion adds to the end and performs Heapify-Up, which traverses the height of the tree (log N)." },
  { question: "Which traversal of a Max-Heap guarantees the elements are visited in descending sorted order?", options: ["In-Order", "Pre-Order", "Post-Order", "None of the above"], correctIndex: 3, explanation: "Heaps are not fully sorted trees (only the parent-child relationship is guaranteed). You must use Heap Sort (repeated extraction) to get sorted order." }
];

